import numpy as np
A=np.array([[int(c) for c in s] for s in demo_in]); B=np.array([[int(c) for c in s] for s in demo_out]);
def comps(X,val):
    vis=set(); out=[]
    for r,c in zip(*np.where(X==val)):
        if (r,c) in vis: continue
        st=[(r,c)];vis.add((r,c)); cells=[]
        while st:
            p=st.pop();cells.append(p)
            for d in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(p[0]+d[0],p[1]+d[1])
                if 0<=q[0]<18 and 0<=q[1]<18 and X[q]==val and q not in vis:vis.add(q);st.append(q)
        out.append(cells)
    return sorted(out,key=len,reverse=True)
